const input = $json;
const COUNTRIES = ["IN", "UK"];
const AUDIENCE_BY_ROLE = {
  contractor: ["all"],
  employee: ["all", "employees"],
  manager: ["all", "employees", "managers"]
};

const country = COUNTRIES.includes(String(input.country || "").toUpperCase()) ? String(input.country).toUpperCase() : "";
const role = AUDIENCE_BY_ROLE[String(input.role || "")] ? String(input.role) : "unknown";
const filterOff = String(input.filter_mode || "strict") === "off";

let countries = country ? [country, "ALL"] : ["ALL"];
let audiences = AUDIENCE_BY_ROLE[role] || ["all"];
let statuses = ["active"];

if (filterOff) {
  countries = ["IN", "UK", "ALL"];
  audiences = ["all", "employees", "managers"];
  statuses = ["active", "archived"];
}

return {
  json: {
    question: String(input.question || "").slice(0, 500),
    country, role,
    filter_mode: filterOff ? "off" : "strict",
    countries, audiences, statuses
  }
};

const MIN_SCORE = 0.35;
const request = $("Build Access Filter").first().json;

const hits = $input.all()
  .map(i => i.json)
  .filter(h => h && h.document && typeof h.score === "number")
  .sort((a, b) => b.score - a.score);

const round = n => Math.round(n * 1000) / 1000;
const good = hits.filter(h => h.score >= MIN_SCORE);

const titles = {};
const scores = {};
for (const h of good) {
  const meta = h.document.metadata || {};
  const id = String(meta.policy_id || "");
  if (!id) continue;
  titles[id] = String(meta.title || "");
  scores[id] = round(h.score);
}

return [{
  json: {
    found: good.length > 0,
    score: hits[0] ? round(hits[0].score) : 0,
    policy_text: good.map(h => String(h.document.pageContent || "")).join("\n\n---\n\n"),
    policy_titles: titles,
    policy_scores: scores,
    question: request.question,
    candidates: hits.map(h => {
      const meta = h.document.metadata || {};
      return { policy_id: meta.policy_id, country: meta.country, audience: meta.audience, status: meta.status, score: round(h.score) };
    })
  }
}];

const pick = $("Pick Matching Policies").first().json;
const request = $("Build Access Filter").first().json;
const text = String(($input.first().json || {}).text || "");

const m = text.match(/SOURCE:\s*(HR-\d+)/);
const policyId = m ? m[1] : "";
const known = !!policyId && pick.policy_titles[policyId] !== undefined;
const answer = text.replace(/^.*SOURCE:.*$/m, "").trim();
const ok = !text.includes("NO_MATCH") && known && answer.length > 0;

return [{
  json: {
    found: ok,
    answer: ok ? answer : "No policy that applies to this person answers the question.",
    policy_source: ok ? policyId + " " + pick.policy_titles[policyId] : "",
    score: ok ? pick.policy_scores[policyId] : pick.score,
    filter_used: { mode: request.filter_mode, countries: request.countries, audiences: request.audiences, statuses: request.statuses },
    candidates: pick.candidates
  }
}];
